def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    supply = float(day_context['supply'])
    day = int(day_context['day'])
    hp = float(my_status['hp'])
    budget = float(my_status['budget'])
    no_water_days = int(my_status['no_water_days'])

    if budget <= 0:
        return 0.0

    alive_opponents = []
    prev_bids = []
    opp_budgets = []
    urgent_opp_count = 0

    for opp_id, opp in opponents_status.items():
        if opp.get('alive'):
            alive_opponents.append(opp)
            opp_budgets.append(float(opp.get('budget', 0.0)))
            if int(opp.get('no_water_days', 0)) >= 1 or float(opp.get('hp', 0)) <= 3:
                urgent_opp_count += 1
            prev = opp.get('previous_trace', {})
            if prev and prev.get('bid') is not None:
                try:
                    prev_bids.append(float(prev.get('bid', 0.0)))
                except Exception:
                    pass

    if not alive_opponents:
        return min(budget, 8.0)

    highest_prev = max(prev_bids) if prev_bids else 0.0
    avg_prev = sum(prev_bids) / len(prev_bids) if prev_bids else 0.0
    richest_opp = max(opp_budgets) if opp_budgets else 0.0

    my_urgent = no_water_days >= 1 or hp <= 3
    very_urgent = no_water_days >= 2 or hp <= 2
    tight_supply = supply <= 17.0
    ample_supply = supply >= 22.0

    if very_urgent:
        bid = max(95.0, highest_prev + 2.5)
        if tight_supply:
            bid += 20.0
        return max(0.0, min(budget, bid))

    if my_urgent:
        bid = max(72.0, avg_prev * 0.9, highest_prev * 0.8)
        if tight_supply:
            bid = max(bid, highest_prev + 1.5)
        return max(0.0, min(budget, bid))

    if ample_supply and hp >= 5 and no_water_days == 0:
        return max(0.0, min(budget, 6.0))

    if highest_prev >= 150.0:
        if tight_supply:
            bid = 58.0
        else:
            bid = 18.0
    elif highest_prev >= 110.0:
        if tight_supply:
            bid = 66.0
        else:
            bid = 22.0
    else:
        bid = max(20.0, min(55.0, avg_prev * 0.6 + 8.0))

    if urgent_opp_count >= 2 and not tight_supply:
        bid *= 0.8

    if richest_opp > budget * 2 and hp >= 5 and no_water_days == 0:
        bid *= 0.85

    if day >= 8 and hp >= 5 and no_water_days == 0:
        bid *= 0.9

    return max(0.0, min(budget, bid))

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 9
    DAILY_SALARY = 90
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    supply = float(day_context['supply'])
    day = day_context['day']

    # Identify alive opponents and extract yesterday bids
    alive_opps = []
    for opp_id, opp in opponents_status.items():
        if opp.get('alive', False):
            alive_opps.append((opp_id, opp))

    yesterday_bids = []
    for _, opp in alive_opps:
        prev = opp.get('previous_trace', {})
        if prev and prev.get('bid') is not None:
            try:
                yesterday_bids.append(float(prev['bid']))
            except Exception:
                pass

    # Base bid pressure estimate from yesterday
    if yesterday_bids:
        highest_prev_bid = max(yesterday_bids)
        avg_prev_bid = sum(yesterday_bids) / float(len(yesterday_bids))
    else:
        highest_prev_bid = 0.0
        avg_prev_bid = DAILY_SALARY * 0.6

    # Tight supply increases urgency; approximate how many water units exist
    # Use explicit int() indexing safety by avoiding list indices.
    supply_units = supply / float(WATER_REQ)

    # Determine aggressiveness based on my HP and supply tightness
    hp = float(my_status['hp'])
    budget = float(my_status['budget'])
    no_water_days = int(my_status['no_water_days'])

    # If I'm already accumulating no-water days or low HP, bid harder
    if hp <= 2.5 or no_water_days >= 2:
        target = DAILY_SALARY * 0.9
    elif hp <= 4.0:
        target = DAILY_SALARY * 0.7
    else:
        # If supply is tight (few units), slightly higher; otherwise undercut
        if supply_units <= 2.0:
            target = DAILY_SALARY * 0.62
        else:
            target = DAILY_SALARY * 0.55

    # Undercut the highest yesterday bid to avoid overpaying, but respond if they were extremely aggressive
    # If highest_prev_bid is huge, we nudge upward; otherwise keep near target.
    if highest_prev_bid >= DAILY_SALARY * 1.8:
        target = max(target, DAILY_SALARY * 0.75)
    elif highest_prev_bid >= DAILY_SALARY * 1.2:
        target = max(target, DAILY_SALARY * 0.65)
    else:
        # keep slight undercut relative to average
        target = min(target, avg_prev_bid * 0.95) if avg_prev_bid > 0 else target

    # Ensure we don't exceed budget
    bid = min(budget, target)

    # Add a tiny deterministic adjustment by day to reduce ties without randomness
    # (bounded to not materially change strategy)
    bid += (float(day) % 3) * 0.75

    # Final clamp
    if bid < 0:
        bid = 0.0
    return float(bid)

def get_bid(day_context, my_status, opponents_status):
    DAILY_SALARY = 80
